{"perguntas":[
 {"t":"multipla","p":"Quando o Senhor mandou Moisés levantar o tabernáculo?","o":["No sétimo dia do primeiro mês","No primeiro dia do primeiro mês","No décimo dia do sétimo mês","No primeiro dia do terceiro mês"],"c":1,"v":2,"e":"No versículo 2 o Senhor diz: 'No primeiro dia do primeiro mês, você levantará o Tabernáculo'."},
 {"t":"multipla","p":"Para que Moisés devia vestir, ungir e consagrar Arão?","o":["Para que ele conduzisse o povo nas jornadas","Para que ele guardasse a arca","Para que ele oficiasse como sacerdote","Para que ele julgasse o povo"],"c":2,"v":13,"e":"O versículo 13 diz que Arão seria consagrado 'para que ele me oficie como sacerdote'."},
 {"t":"multipla","p":"O que Moisés colocou sobre a arca, depois de pôr nela o testemunho e os varais?","o":["O candelabro","O propiciatório","Os pães da proposição","O altar de ouro"],"c":1,"v":20,"e":"O versículo 20 diz que Moisés 'colocou o propiciatório sobre ela'."},
 {"t":"multipla","p":"Onde Moisés pôs a mesa na tenda da congregação?","o":["Ao lado sul, junto ao candelabro","Dentro do véu, junto à arca","Entre a tenda e o altar do holocausto","Ao lado norte, fora do véu"],"c":3,"v":22,"e":"O versículo 22 diz que a mesa ficou 'ao lado do tabernáculo, para o norte, fora do véu'."},
 {"t":"multipla","p":"O que Moisés acendeu sobre o altar de ouro?","o":["O holocausto","As lâmpadas","O incenso aromático","A oferta de cereais"],"c":2,"v":27,"e":"O versículo 27 diz que ele 'acendeu sobre ele o incenso aromático'."},
 {"t":"cv","p":"Moisés, Arão e seus filhos lavavam as mãos e os pés na bacia.","c":true,"v":31,"e":"O versículo 31 diz exatamente que eles lavavam as mãos e os pés nela."},
 {"t":"cv","p":"Quando a nuvem cobriu a tenda, Moisés entrou nela para ver a glória do Senhor.","c":false,"v":35,"e":"O versículo 35 diz que Moisés não podia entrar na tenda, pois a nuvem permanecia sobre ela."},
 {"t":"cv","p":"De dia a nuvem do Senhor ficava sobre o tabernáculo, e à noite havia fogo nele, à vista de toda a casa de Israel.","c":true,"v":38,"e":"O versículo 38 descreve a nuvem de dia e o fogo à noite, à vista de toda a casa de Israel."}
]}

Êxodo 39 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Como são chamadas as pedras sardônicas colocadas sobre as ombreiras do éfode?","o":["Pedras de lembrança para os filhos de Israel","Pedras do testemunho","Pedras da aliança","Pedras de fundamento do santuário"],"c":0,"v":7,"e":"O versículo 7 diz que foram postas nas ombreiras do éfode como pedras de lembrança para os filhos de Israel."},
 {"t":"multipla","p":"Qual era o formato do peitoral?","o":["Redondo, com um palmo de diâmetro","Triangular, com um palmo de cada lado","Retangular, com dois palmos por um","Quadrado e dobrado, com um palmo de cada lado"],"c":3,"v":9,"e":"O versículo 9 diz que o peitoral era quadrado e dobrado, com um palmo de comprimento e um de largura."},
 {"t":"multipla","p":"O que estava esculpido nas doze pedras do peitoral?","o":["As palavras \"Santidade ao Senhor\"","Os nomes dos filhos de Israel, um para cada tribo","Os nomes de Moisés e Arão","Os Dez Mandamentos"],"c":1,"v":14,"e":"O versículo 14 diz que as pedras tinham os nomes dos filhos de Israel, cada uma com o seu nome para as doze tribos."},
 {"t":"multipla","p":"Com o que o peitoral foi ligado às argolas do éfode?","o":["Uma corrente de prata","Um cordão de linho branco","Uma fita azul","Uma fivela de bronze"],"c":2,"v":21,"e":"O versículo 21 diz que ligaram o peitoral às argolas do éfode com uma fita azul, para que não se separasse do éfode."},
 {"t":"multipla","p":"O que foi colocado, alternadamente, em toda a orla do manto?","o":["Pedras preciosas e argolas de ouro","Campainhas de ouro e romãs","Franjas azuis e fios de prata","Flores de linho e sinos de bronze"],"c":1,"v":26,"e":"O versículo 26 descreve uma campainha e uma romã, outra campainha e outra romã, em toda a orla do manto."},
 {"t":"cv","p":"Na lâmina de ouro puro da coroa sagrada estava gravado: Santidade ao Senhor.","c":true,"v":30,"e":"O versículo 30 diz que a lâmina de ouro puro tinha gravado, como um sinete, \"Santidade ao Senhor\"."},
 {"t":"cv","p":"Concluída a obra, os filhos de Israel trouxeram a Moisés o tabernáculo, a tenda e todos os seus utensílios.","c":true,"v":33,"e":"O versículo 33 diz que trouxeram a Moisés o tabernáculo, a tenda e todos os seus utensílios."},
 {"t":"cv","p":"Ao ver toda a obra, Moisés mandou refazer as partes que não estavam conforme a ordem do Senhor.","c":false,"v":43,"e":"O versículo 43 diz que Moisés viu que tinham feito tudo conforme o Senhor havia ordenado e então os abençoou."}
]}
